#' Define and create all model processes
#'

#' @param variables_list A list of model variables as generated by [create_variables()]
#' @param events_list A list of the model events as generated by [create_events()]
#' @param parameters_list A list of model parameters as generated by [get_parameters()]
#' @param renderer An individual-package render object
#'
#' @family processes
#' @export
create_processes <- function(
  variables_list,
  events_list,
  parameters_list,
  renderer
) {
  # Open a list of processes to store the model processes in:
  processes_list <- list(
    # ===============================
    # Disease State Progression
    # ===============================
    SE_process = create_SE_process(
      variables_list = variables_list,
      events_list = events_list,
      parameters_list = parameters_list,
      renderer = renderer
    ),

    EI_process = create_EI_process(
      variables_list = variables_list,
      events_list = events_list,
      parameters_list = parameters_list,
      renderer= renderer
    ),

    I_mild_R_process = create_I_mild_R_process(
      variables_list = variables_list,
      events_list = events_list,
      parameters_list = parameters_list,
      renderer= renderer
    ),

    I_hosp_exit_process = create_I_hosp_exit_process(
      variables_list = variables_list,
      events_list = events_list,
      parameters_list = parameters_list,
      renderer= renderer
    )
  )

  # ===============================
  # ENDEMIC DISEASE MODE
  # ===============================
  if (parameters_list$endemic_or_epidemic == "endemic") {
    processes_list <- c(
      processes_list,
      list(
        RS_process = create_RS_process(
          variables_list = variables_list,
          events_list = events_list,
          parameters_list = parameters_list
        )
      ),
      list(
        external_source_process = create_external_source_process(
          variables_list = variables_list,
          events_list = events_list,
          parameters_list = parameters_list,
          renderer = renderer
        )
      )
    )
  }

  # ===============================
  # Rendering processes
  # ===============================
  # health_render_process
  processes_list <- c(
    processes_list,
    renderer = individual::categorical_count_renderer_process(
      renderer,
      variables_list$disease_state,
      c('S', 'E', 'I_mild', 'I_hosp', 'R', 'D')
    )
  )

  # Return the model processes:
  return(processes_list)
}

#' Create process governing susceptible to exposed disease state transition
#'
#' @inheritParams create_processes
#'
#' @family processes
#' @export
create_SE_process <- function(
  variables_list,
  events_list,
  parameters_list,
  renderer
) {
  ## Pre-calculating the things that only have to be calculated once

  # Every setting is held as an integer vector with one entry per person giving
  # the id of the location they belong to (0 = no location of that type). The
  # number of infectious people in every location is then a single tabulate()
  # and the force of infection (FOI) of every location is one vector expression.
  population <- parameters_list$human_population

  ##### HOUSEHOLDS #####
  num_households <- max(as.numeric(variables_list$household$get_categories()))
  household_id <- get_location_ids(variables_list$household)
  household_size <- tabulate(household_id, nbins = num_households)
  household_intervention <- prepare_se_intervention(
    parameters_list,
    setting = "household",
    riskiness = parameters_list$household_specific_riskiness
  )

  ##### WORKPLACES #####
  num_workplaces <- max(as.numeric(variables_list$workplace$get_categories()))
  workplace_id <- get_location_ids(variables_list$workplace)
  workplace_size <- tabulate(workplace_id, nbins = num_workplaces)
  workplace_intervention <- prepare_se_intervention(
    parameters_list,
    setting = "workplace",
    riskiness = parameters_list$workplace_specific_riskiness
  )

  ##### SCHOOLS #####
  num_schools <- max(as.numeric(variables_list$school$get_categories()))
  school_id <- get_location_ids(variables_list$school)
  school_size <- tabulate(school_id, nbins = num_schools)
  school_intervention <- prepare_se_intervention(
    parameters_list,
    setting = "school",
    riskiness = parameters_list$school_specific_riskiness
  )

  ##### LEISURE #####
  # Leisure occupancy is dynamically updated each day, so we don't calculate that here.
  # We only store the 7 possible visits of each person (one row per person) and the ids of the
  # leisure locations that can be visited (leisure_locations excludes the "0" = stays-home category).
  leisure_possible_visits <- unlist(variables_list$leisure$get_values())
  if (length(leisure_possible_visits) != 7 * population) {
    stop("every individual must have exactly 7 possible leisure visits (one per day of the week)")
  }
  leisure_possible_visits <- matrix(leisure_possible_visits, ncol = 7, byrow = TRUE)
  leisure_locations <- sort(as.numeric(parameters_list$leisure_indices))
  leisure_locations <- leisure_locations[leisure_locations != 0] # removing the "0" category which is not visited
  num_leisure_locations <- length(leisure_locations)
  leisure_intervention <- prepare_se_intervention(
    parameters_list,
    setting = "leisure",
    riskiness = parameters_list$leisure_specific_riskiness
  )
  # Position (1:num_leisure_locations) in leisure_locations of the venue each person visits
  # today, 0 = none, and the number of people at each venue today. These are set at the first
  # call (so that a simulation resumed from a saved state picks up the saved assignment)
  # and then at every daily redraw.
  leisure_position <- NULL
  leisure_size <- NULL
  set_leisure_position <- function(leisure_visit) {
    leisure_position <<- match(leisure_visit, leisure_locations, nomatch = 0L)
    leisure_size <<- tabulate(leisure_position, nbins = num_leisure_locations)
  }

  ## Process Function
  function(t) {
    ## Indices of all infectious individuals
    infectious <- variables_list$disease_state$get_index_of("I_mild")$to_vector()

    #=== time-varying modification of betas ===#
    #=================================#
    # When time-varying transmission is on, each setting-specific beta is a vector with one
    # value per simulated day; the timestep t is converted to a day via
    # timestep_to_day() (1/dt timesteps per day) and that day's value is used.
    # When time-varying transmission is off, each setting-specific beta is a single constant
    # value used for every timestep.
    if (parameters_list$time_varying_transmission_on) {
      day <- timestep_to_day(t, parameters_list$dt)
      beta_household_t <- parameters_list$beta_household[day]
      beta_workplace_t <- parameters_list$beta_workplace[day]
      beta_school_t <- parameters_list$beta_school[day]
      beta_leisure_t <- parameters_list$beta_leisure[day]
      beta_community_t <- parameters_list$beta_community[day]
    } else {
      beta_household_t <- parameters_list$beta_household
      beta_workplace_t <- parameters_list$beta_workplace
      beta_school_t <- parameters_list$beta_school
      beta_leisure_t <- parameters_list$beta_leisure
      beta_community_t <- parameters_list$beta_community
    }

    #=== Household FOI ===#
    #=====================#
    # The household FOI of each individual (if HH size = 1, FOI = 0)
    household_FOI <- calculate_location_foi(
      location_id = household_id,
      infectious = infectious,
      size = household_size,
      riskiness = parameters_list$household_specific_riskiness,
      beta = beta_household_t,
      t = t,
      intervention = household_intervention,
      min_size = 2L
    )

    #=== Workplace FOI ===#
    #=====================#
    workplace_FOI <- calculate_location_foi(
      location_id = workplace_id,
      infectious = infectious,
      size = workplace_size,
      riskiness = parameters_list$workplace_specific_riskiness,
      beta = beta_workplace_t,
      t = t,
      intervention = workplace_intervention
    )

    #=== School FOI ===#
    #==================#
    school_FOI <- calculate_location_foi(
      location_id = school_id,
      infectious = infectious,
      size = school_size,
      riskiness = parameters_list$school_specific_riskiness,
      beta = beta_school_t,
      t = t,
      intervention = school_intervention
    )

    #=== Leisure FOI ===#
    #=====================#
    if (is.null(leisure_position)) {
      set_leisure_position(as.numeric(variables_list$specific_leisure$get_values()))
    }
    if ((t * parameters_list$dt) == floor(t * parameters_list$dt)) {
      # For each individual, work out which leisure location they go to that particular day. 0 = they don't go to any
      # Sampling which leisure location actually visited (0 = visit none and staying home) from the leisure locations
      # individuals have associated with them (and could visit). One dqrng draw per person, in person order.
      leisure_visit <- leisure_possible_visits[
        seq_len(population) + (dqrng::dqsample.int(n = 7, size = population, replace = TRUE) - 1L) * population
      ]

      # Updating the leisure setting visited that day
      ## Note that we include all leisure locations as categories irrespective of whether they're visited on a particular day
      ## Doesn't affect the FOI calculation, as places with no visits on a day don't update the FOI vector
      ## Also note that parameters_list$leisure_indices aren't 1:num_leisure as i) it includes 0 (no leisure visited); and
      ## 2) as part of the leisure variable creation in variables.R, some initially created leisure locations
      ##    don't feature in the RaggedInteger vector, and so these locations are removed as indices.
      variables_list$specific_leisure$queue_update(values = leisure_visit) #  update the states with leisure_visit for that day
      set_leisure_position(leisure_visit)
    }

    # Calculating leisure-specific FOI for each individual
    ## Note that leisure_specific_riskiness (and uvc_leisure) use indices 1:num_leisure to index the leisure
    ## locations, i.e. the position of a venue in leisure_locations (this is in contrast to leisure_indices,
    ## which uses the original indices from their generation, and which span 1 to max(leisure_indices) with
    ## some gaps). Venues nobody visits today have no size (0 / 0) and are never looked up.
    ## The size of a venue is the number of people visiting it today (leisure_size) -
    ## this calculation needs more in it
    leisure_FOI <- calculate_location_foi(
      location_id = leisure_position,
      infectious = infectious,
      size = leisure_size,
      riskiness = parameters_list$leisure_specific_riskiness,
      beta = beta_leisure_t,
      t = t,
      intervention = leisure_intervention
    )

    #=== Community FOI ===#
    #=====================#
    ### Calculate Community FOI (real-valued for all individuals)
    #### NOTE: Double check whether the "/N" is correct here - not sure currently
    community_FOI <- beta_community_t *
      length(infectious) /
      parameters_list$human_population

    #=== Total FOI ===#
    #=================#

    # Sum the household, workplace, school leisure, and community FOIs to get the total FOI for each
    # individual:
    total_FOI <- household_FOI +
      workplace_FOI +
      school_FOI +
      leisure_FOI +
      community_FOI

    # Render the setting-specific FOIs is diagnostic rendering turned on:
    if (parameters_list$render_diagnostics) {
      renderer$render('FOI_household', max(household_FOI), t)
      renderer$render('FOI_workplace', max(workplace_FOI), t)
      renderer$render('FOI_school', max(school_FOI), t)
      renderer$render('FOI_leisure', max(leisure_FOI), t)
      renderer$render('FOI_community', max(community_FOI), t)
      renderer$render('FOI_total', max(total_FOI), t)
    }

    # Calculate the probability of getting infected in the current interval for each individual:
    p_inf <- 1 - exp(-total_FOI * parameters_list$dt)

    # Get the indices of all susceptible individuals in the current timestep:
    S <- variables_list$disease_state$get_index_of("S")

    # Get the infection probability for each currently susceptible individual:
    p_inf_currently_S <- p_inf[S$to_vector()]

    # Sample susceptible individuals using their infection probability to determine who gets infected:
    S$sample(rate = p_inf_currently_S)

    # Render the number of people going from susceptible to infected:
    renderer$render('E_new', S$size(), t)

    # Queue an update to the infectious state of the newly infected susceptible individuals to Exposed:
    variables_list$disease_state$queue_update(value = "E", index = S)
  }
}

#' Force of infection of every location of one setting type, indexed back to people
#'
#' For each location the FOI is
#' `riskiness * beta * n_infectious / size`, multiplied by `(1 - efficacy)` once an
#' intervention has been switched on there. All locations are handled with vector
#' operations, and the result is looked up per person with `foi[location_id]`.
#'
#' @param location_id Integer vector with one entry per person: the id of the
#'   location the person is in, or 0 if they are in none.
#' @param infectious Indices of the infectious people.
#' @param size Number of people in each location (`tabulate(location_id)`).
#' @param riskiness Setting-specific riskiness of each location.
#' @param beta Transmission rate of the setting at this timestep.
#' @param t The timestep.
#' @param intervention `NULL`, or the list returned by [prepare_se_intervention()].
#' @param min_size Locations with fewer people than this have an FOI of 0 (2 for
#'   households: a single-person household has no one to infect them).
#'
#' @return A numeric vector with the FOI experienced by each person from this setting.
#' @noRd
calculate_location_foi <- function(
  location_id,
  infectious,
  size,
  riskiness,
  beta,
  t,
  intervention = NULL,
  min_size = 1L
) {
  n_infectious <- tabulate(location_id[infectious], nbins = length(size))
  foi <- riskiness * beta * n_infectious / size

  if (!is.null(intervention) && t > intervention$timestep) {
    locations <- intervention$locations
    foi[locations] <- intervention$riskiness *
      (beta * n_infectious[locations] / size[locations])
  }

  # Empty locations (0 / 0) are never looked up by anybody, single-person households have FOI 0
  foi[size < min_size] <- 0
  c(0, foi)[location_id + 1L]
}

#' Pre-compute the constant part of an intervention for one setting type
#'
#' @param parameters_list A list of model parameters as generated by [get_parameters()]
#' @param setting One of `"household"`, `"workplace"`, `"school"` or `"leisure"`
#' @param riskiness The setting-specific riskiness of every location of the setting
#'
#' @return `NULL` if the intervention is not active in the setting. Otherwise a list
#'   with the `locations` it applies to (every location: uncovered ones have efficacy
#'   0), their `riskiness` already multiplied by `(1 - efficacy)`, and the switch-on
#'   `timestep` (the intervention applies when `t > timestep`).
#' @noRd
prepare_se_intervention <- function(parameters_list, setting, riskiness) {
  if (!isTRUE(parameters_list[[paste0("intervention_", setting, "_active")]])) {
    return(NULL)
  }
  efficacy <- parameters_list[[paste0(setting, "_specific_efficacy")]]
  locations <- seq_along(efficacy)
  list(
    locations = locations,
    riskiness = riskiness[locations] * (1 - efficacy),
    timestep = parameters_list[[paste0("intervention_", setting, "_timestep")]]
  )
}

#' The location id of every person, read from a categorical location variable
#'
#' Equivalent to `as.integer(variable$get_values())` but built from one
#' `get_index_of()` per category. `CategoricalVariable$get_values()` costs
#' (people x categories) per call, which is minutes for the household variable
#' at tens of thousands of people.
#'
#' @param variable An `individual::CategoricalVariable` whose categories are the
#'   location ids as text (`"0"` meaning no location).
#'
#' @return An integer vector, one entry per person, 0 for people in no location.
#' @noRd
get_location_ids <- function(variable) {
  location_id <- integer(variable$size())
  for (category in setdiff(variable$get_categories(), "0")) {
    location_id[variable$get_index_of(category)$to_vector()] <- as.integer(category)
  }
  location_id
}


#' Create process governing exposed to infectious disease state transition
#'
#' Performs an age-dependent binomial split of newly transitioning exposed
#' individuals between I_mild and I_hosp. Counts `H_new` at entry to I_hosp.
#'
#' @inheritParams create_processes
#'
#' @family processes
#' @export
create_EI_process <- function(
  variables_list,
  events_list,
  parameters_list,
  renderer
) {
  function(t) {
    # Get exposed individuals not yet scheduled into either EI event
    E <- variables_list$disease_state$get_index_of("E")
    already_scheduled <- events_list$EI_mild_event$get_scheduled()
    already_scheduled$or(events_list$EIhosp_event$get_scheduled())
    E$and(already_scheduled$not(inplace = TRUE))

    if (E$size() == 0) return()
    E_idx <- E$to_vector()

    # Build per-person hospitalization probability based on age class
    p_hosp <- rep(NA_real_, length(E_idx))
    child_idx <- variables_list$age_class$get_index_of("child")$to_vector()
    adult_idx <- variables_list$age_class$get_index_of("adult")$to_vector()
    elderly_idx <- variables_list$age_class$get_index_of("elderly")$to_vector()
    p_hosp[E_idx %in% child_idx] <- parameters_list$prob_hosp_child
    p_hosp[E_idx %in% adult_idx] <- parameters_list$prob_hosp_adult
    p_hosp[E_idx %in% elderly_idx] <- parameters_list$prob_hosp_elderly

    # Guard: every exposed individual must have been matched to one of the
    # three age classes. NA in p_hosp would propagate to NA in hosp_draw and
    # silently drop the individual from both the mild and hosp branches.
    if (anyNA(p_hosp)) {
      stop(sprintf(
        "create_EI_process: p_hosp has %d NA entries — some exposed individuals do not match any age class",
        sum(is.na(p_hosp))
      ))
    }

    # Binomial split
    hosp_draw <- rbinom(length(E_idx), size = 1, prob = p_hosp)

    # Gamma-distributed delay until E -> I transition
    I_times <- round(
      (rgamma(
        n = length(E_idx),
        shape = 2,
        rate = 2 / parameters_list$duration_exposed
      ) + 1) / parameters_list$dt
    )

    mild_mask <- hosp_draw == 0
    hosp_mask <- hosp_draw == 1

    if (any(mild_mask)) {
      events_list$EI_mild_event$schedule(
        target = E_idx[mild_mask],
        delay = I_times[mild_mask]
      )
    }
    if (any(hosp_mask)) {
      events_list$EIhosp_event$schedule(
        target = E_idx[hosp_mask],
        delay = I_times[hosp_mask]
      )
    }

    # Count new hospitalizations at the moment severity is decided
    renderer$render("H_new", sum(hosp_mask), t)
  }
}

#' Create process governing I_mild -> R disease state transition
#'
#' All mild cases recover; no branching.
#'
#' @inheritParams create_processes
#'
#' @family processes
#' @export
create_I_mild_R_process <- function(
  variables_list,
  events_list,
  parameters_list,
  renderer
) {
  function(t) {
    I_mild <- variables_list$disease_state$get_index_of("I_mild")
    already_scheduled <- events_list$I_mild_R_event$get_scheduled()
    I_mild$and(already_scheduled$not(inplace = TRUE))

    if (I_mild$size() == 0) return()

    R_times <- round(
      (rgamma(
        n = I_mild$size(),
        shape = 2,
        rate = 2 / parameters_list$duration_infectious
      ) + 1) / parameters_list$dt
    )

    events_list$I_mild_R_event$schedule(target = I_mild, delay = R_times)
  }
}

#' Create process governing I_hosp -> {R, D} disease state transition
#'
#' Performs an age-dependent binomial split between recovery and death.
#' Counts `D_new` at the moment the death decision is made.
#'
#' @inheritParams create_processes
#'
#' @family processes
#' @export
create_I_hosp_exit_process <- function(
  variables_list,
  events_list,
  parameters_list,
  renderer
) {
  function(t) {
    # Get I_hosp individuals not yet scheduled into either exit event
    I_hosp <- variables_list$disease_state$get_index_of("I_hosp")
    already_scheduled <- events_list$I_hosp_R_event$get_scheduled()
    already_scheduled$or(events_list$I_hosp_D_event$get_scheduled())
    I_hosp$and(already_scheduled$not(inplace = TRUE))

    if (I_hosp$size() == 0) return()
    I_hosp_idx <- I_hosp$to_vector()

    # Build per-person death probability based on age class
    p_death <- rep(NA_real_, length(I_hosp_idx))
    child_idx <- variables_list$age_class$get_index_of("child")$to_vector()
    adult_idx <- variables_list$age_class$get_index_of("adult")$to_vector()
    elderly_idx <- variables_list$age_class$get_index_of("elderly")$to_vector()
    p_death[I_hosp_idx %in% child_idx] <- parameters_list$prob_death_hosp_child
    p_death[I_hosp_idx %in% adult_idx] <- parameters_list$prob_death_hosp_adult
    p_death[I_hosp_idx %in% elderly_idx] <- parameters_list$prob_death_hosp_elderly

    # Guard: every hospitalized individual must have been matched to one of
    # the three age classes. NA in p_death would propagate to NA in death_draw
    # and silently drop the individual from both the recover and die branches.
    if (anyNA(p_death)) {
      stop(sprintf(
        "create_I_hosp_exit_process: p_death has %d NA entries — some hospitalized individuals do not match any age class",
        sum(is.na(p_death))
      ))
    }

    # Binomial split
    death_draw <- rbinom(length(I_hosp_idx), size = 1, prob = p_death)

    # Gamma-distributed delay (reusing duration_infectious)
    exit_times <- round(
      (rgamma(
        n = length(I_hosp_idx),
        shape = 2,
        rate = 2 / parameters_list$duration_hospitalized
      ) + 1) / parameters_list$dt
    )

    recover_mask <- death_draw == 0
    death_mask <- death_draw == 1

    if (any(recover_mask)) {
      events_list$I_hosp_R_event$schedule(
        target = I_hosp_idx[recover_mask],
        delay = exit_times[recover_mask]
      )
    }
    if (any(death_mask)) {
      events_list$I_hosp_D_event$schedule(
        target = I_hosp_idx[death_mask],
        delay = exit_times[death_mask]
      )
    }

    renderer$render("D_new", sum(death_mask), t)
  }
}

#' Create process governing recovered (and immune) back to susceptible disease state transition
#'
#' @inheritParams create_processes
#'
#' @family processes
#' @export
create_RS_process <- function(variables_list, events_list, parameters_list) {
  function(t) {
    # Get the indices of currently recovered and immune individuals:
    R <- variables_list$disease_state$get_index_of("R")

    # Get the indices of individuals with I to R transitions already scheduled:
    RS_already_scheduled <- events_list$RS_event$get_scheduled()

    # Get the indices of infectious individuals without R to S transitions already scheduled:
    R$and(RS_already_scheduled$not(inplace = TRUE))

    # Calculate recovery times for infectious individuals without transitions scheduled:
    S_times <- round(
      rgamma(
        n = R$size(),
        shape = 1,
        rate = 1 / parameters_list$duration_immune
      ) /
        parameters_list$dt
    )

    # Schedule the recovery events for infectious individuals without transitions scheduled:
    events_list$RS_event$schedule(target = R, delay = S_times)
  }
}

#' Create process governing exposed to infectious disease state transition
#'
#' @inheritParams create_processes
#'
#' @family processes
#' @export
create_external_source_process <- function(
  variables_list,
  events_list,
  parameters_list,
  renderer
) {
  function(t) {
    # Get the indices of all susceptible individuals:
    S_endemic <- variables_list$disease_state$get_index_of("S")

    # Calculate the probability of getting infected in the current interval for each individual:
    p_inf_ext <- 1 -
      exp(-parameters_list$prob_inf_external * parameters_list$dt)

    # Sample susceptible individuals using their infection probability to determine who gets infected:
    S_endemic$sample(rate = p_inf_ext)

    # Queue an update to the infectious state of the newly infected susceptible individuals to Exposed:
    variables_list$disease_state$queue_update(value = "E", index = S_endemic)

    # Render the number of individuals infected through the external mechanism
    renderer$render('n_external_infections', S_endemic$size(), t)
  }
}
